insert into public.posts(id,slug,title_kn,title_en,title_hi,title_translit,summary_kn,summary_en,summary_hi,body_html,body_en,body_hi,event_date,event_place,published_at,type,status,thumbnail_url,is_seed) values('00000000-0000-4000-8000-000000001001','seed-moodbidri-basadi','ಮೂಡುಬಿದಿರೆಯ ಸಾವಿರ ಕಂಬದ ಬಸದಿಯ ಕಲಾ ವೈಭವ','Moodbidri thousand pillar basadi','मूडबिद्री की सहस्र स्तंभ बसदि का कला वैभव','moodbidri basadi heritage','ಶತಮಾನಗಳ ಶಿಲ್ಪಕಲೆ, ಸಾಂಸ್ಕೃತಿಕ ಸ್ಮೃತಿ ಮತ್ತು ಜೈನ ಪರಂಪರೆಯ ಸುಂದರ ಪರಿಚಯ.','Centuries of sculpture, cultural memory and a graceful introduction to Jain heritage.','सदियों की शिल्पकला, सांस्कृतिक स्मृति और जैन परंपरा का सुंदर परिचय।','<p>ಶತಮಾನಗಳ ಶಿಲ್ಪಕಲೆ, ಸಾಂಸ್ಕೃತಿಕ ಸ್ಮೃತಿ ಮತ್ತು ಜೈನ ಪರಂಪರೆಯ ಸುಂದರ ಪರಿಚಯ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','<p>Centuries of sculpture, cultural memory and a graceful introduction to Jain heritage.</p><p>This is a sample article introducing our community''s heritage, faith and values. Through this page you can see how a report reads, how event dates appear and how related topics are surfaced.</p><h2>Carrying the tradition forward</h2><p>Ahimsa, coexistence and service hold a special place in Jain culture. Recording the history of our towns and the achievements of our community is an invaluable gift to the next generation.</p><p>The content here is only a sample prepared to demonstrate the design. Real reports and event details will be published after editorial review.</p>','<p>सदियों की शिल्पकला, सांस्कृतिक स्मृति और जैन परंपरा का सुंदर परिचय।</p><p>यह हमारे समुदाय की परंपरा, आस्था और जीवनमूल्यों का परिचय देने वाला एक नमूना लेख है। इस पृष्ठ के माध्यम से समाचार पढ़ने का अनुभव, कार्यक्रम की तिथि और संबंधित विषय देखे जा सकते हैं।</p><h2>परंपरा के साथ अगला कदम</h2><p>जैन संस्कृति में अहिंसा, सहजीवन और सेवा का विशेष स्थान है। हमारे गाँव-शहरों का इतिहास और समाज की उपलब्धियाँ दर्ज करना अगली पीढ़ी के लिए अमूल्य योगदान है।</p><p>यहाँ दी गई सामग्री केवल डिज़ाइन दिखाने के लिए तैयार किया गया नमूना है। वास्तविक रिपोर्ट और कार्यक्रमों की जानकारी संपादकीय समीक्षा के बाद प्रकाशित की जाएगी।</p>','2026-09-14','ಮೂಡುಬಿದಿರೆ','2026-09-16T06:30:00Z','article','published','/images/temple.webp',true) on conflict(id) do nothing;
